#!/usr/bin/env python3
"""Robust microgrid islanding dispatch solver (PySCIPOpt)."""
import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
SOL_PATH = os.path.join(OUT_DIR, "solution.csv")

# ---------------------------------------------------------------- data load
def load_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)
    def read_csv(name):
        with open(os.path.join(DATA_DIR, name)) as f:
            return list(csv.DictReader(f))
    time_periods = read_csv("time_periods.csv")
    generators = read_csv("generators.csv")
    storage = read_csv("storage_units.csv")
    evs = read_csv("ev_clusters.csv")
    renew = read_csv("renewable_forecast.csv")
    grid = read_csv("grid_limits.csv")
    dr = read_csv("demand_response.csv")
    scenarios = read_csv("scenarios.csv")
    sh = read_csv("scenario_hourly.csv")
    return cfg, time_periods, generators, storage, evs, renew, grid, dr, scenarios, sh

def main():
    cfg, time_periods, generators, storage, evs, renew, grid, dr, scenarios, sh = load_data()
    H = cfg["planning_hours"]
    hours = list(range(H))

    base_load = {int(r["hour"]): float(r["base_load_kw"]) for r in time_periods}
    crit_load = {int(r["hour"]): float(r["critical_load_kw"]) for r in time_periods}
    tariff = {int(r["hour"]): float(r["tariff_import_per_kwh"]) for r in time_periods}

    G = [r["generator_id"] for r in generators]
    gen = {r["generator_id"]: r for r in generators}
    B = [r["storage_id"] for r in storage]
    bat = {r["storage_id"]: r for r in storage}
    E = [r["cluster_id"] for r in evs]
    ev = {r["cluster_id"]: r for r in evs}

    pv = {int(r["hour"]): float(r["pv_kw"]) for r in renew}
    wind = {int(r["hour"]): float(r["wind_kw"]) for r in renew}
    gridcap = {int(r["hour"]): float(r["import_cap_kw"]) for r in grid}

    # DR: only hours present in file
    dr_hours = [int(r["hour"]) for r in dr]
    dr_max = {int(r["hour"]): float(r["max_curtail_kw"]) for r in dr}
    dr_reb_hour = {int(r["hour"]): int(r["rebound_hour"]) for r in dr}
    dr_frac = {int(r["hour"]): float(r["rebound_fraction"]) for r in dr}
    dr_cost = {int(r["hour"]): float(r["discomfort_cost_per_kwh"]) for r in dr}

    S = [r["scenario_id"] for r in scenarios]
    prob = {r["scenario_id"]: float(r["probability"]) for r in scenarios}

    shd = {}
    for r in sh:
        shd[(r["scenario_id"], int(r["hour"]))] = r

    alpha = cfg["tail_risk_alpha"]
    tail_w = cfg["tail_risk_weight"]
    curtail_cost = cfg["renewable_curtailment_cost_per_kwh"]
    shed_cost = cfg["load_shed_penalty_per_kwh"]
    gf_frac = cfg["grid_forming_storage_reserve_fraction"]
    island_sync = cfg["island_min_synchronous_reserve_kw"]
    island_inertia = cfg["island_min_inertia_score"]
    max_consec_dr = cfg["max_consecutive_dr_hours"]
    max_daily_dr = cfg["max_daily_dr_kwh"]
    em_cap = cfg["scenario_emissions_cap_kg"]
    init_u = {k: int(v) for k, v in cfg["initial_commitment"].items()}

    # ------------------------------------------------------------- model
    model = Model("robust_microgrid")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            time_limit = min(time_limit, float(env))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)
    model.setMinimize()

    # here-and-now commitment
    u = {}
    v = {}
    for g in G:
        for t in hours:
            u[(g, t)] = model.addVar(name=f"u_{g}_{t}", vtype="B", lb=0, ub=1, obj=0.0)
            v[(g, t)] = model.addVar(name=f"v_{g}_{t}", vtype="B", lb=0, ub=1, obj=float(gen[g]["startup_cost"]))
    # startup logic
    for g in G:
        for t in hours:
            prev = init_u.get(g, 0) if t == 0 else u[(g, t - 1)]
            if t == 0:
                model.addCons(u[(g, 0)] - prev <= v[(g, 0)], name=f"su_{g}_{t}")
                model.addCons(v[(g, 0)] >= u[(g, 0)] - prev, name=f"su2_{g}_{t}")
            else:
                model.addCons(u[(g, t)] - u[(g, t - 1)] <= v[(g, t)], name=f"su_{g}_{t}")
                model.addCons(v[(g, t)] >= u[(g, t)] - u[(g, t - 1)], name=f"su2_{g}_{t}")
            model.addCons(v[(g, t)] <= u[(g, t)], name=f"su3_{g}_{t}")
            # min up
            mu = int(gen[g]["min_up_hours"])
            if mu >= 1:
                terms = [v[(g, max(0, tau))] for tau in range(t - mu + 1, t + 1)]
                model.addCons(quicksum(terms) >= u[(g, t)], name=f"mu_{g}_{t}")
            # min down
            md = int(gen[g]["min_down_hours"])
            if md >= 1:
                terms = []
                for tau in range(t - md + 1, t + 1):
                    if tau < 0:
                        terms.append(1 - init_u.get(g, 0))
                    else:
                        terms.append(1 - v[(g, tau)])
                model.addCons(quicksum(terms) >= 1 - u[(g, t)], name=f"md_{g}_{t}")

    # recourse variables
    P = {}; imp = {}; chb = {}; dcb = {}; socb = {}
    che = {}; dce = {}; soce = {}
    genr = {}; curr = {}; cut = {}; shed = {}
    Rg = {}; Rb = {}; Re = {}
    ydr = {}; wbat = {}
    for s in S:
        for t in hours:
            for g in G:
                P[(s, t, g)] = model.addVar(name=f"P_{s}_{t}_{g}", vtype="C", lb=0, ub=float(gen[g]["max_kw"]))
            imp[(s, t)] = model.addVar(name=f"imp_{s}_{t}", vtype="C", lb=0, ub=float(max(gridcap.values())))
            for b in B:
                chb[(s, t, b)] = model.addVar(name=f"chb_{s}_{t}_{b}", vtype="C", lb=0, ub=float(bat[b]["max_charge_kw"]))
                dcb[(s, t, b)] = model.addVar(name=f"dcb_{s}_{t}_{b}", vtype="C", lb=0, ub=float(bat[b]["max_discharge_kw"]))
                socb[(s, t, b)] = model.addVar(name=f"socb_{s}_{t}_{b}", vtype="C", lb=float(bat[b]["min_soc_kwh"]), ub=float(bat[b]["max_soc_kwh"]))
                wbat[(s, t, b)] = model.addVar(name=f"wbat_{s}_{t}_{b}", vtype="B", lb=0, ub=1)
            for e in E:
                che[(s, t, e)] = model.addVar(name=f"che_{s}_{t}_{e}", vtype="C", lb=0, ub=float(ev[e]["max_charge_kw"]))
                dce[(s, t, e)] = model.addVar(name=f"dce_{s}_{t}_{e}", vtype="C", lb=0, ub=float(ev[e]["max_discharge_kw"]))
                soce[(s, t, e)] = model.addVar(name=f"soce_{s}_{t}_{e}", vtype="C", lb=float(ev[e]["min_soc_kwh"]), ub=float(ev[e]["max_soc_kwh"]))
            for r in ("pv", "wind"):
                genr[(s, t, r)] = model.addVar(name=f"gen_{s}_{t}_{r}", vtype="C", lb=0)
                curr[(s, t, r)] = model.addVar(name=f"cur_{s}_{t}_{r}", vtype="C", lb=0)
            cut[(s, t)] = model.addVar(name=f"cut_{s}_{t}", vtype="C", lb=0, ub=dr_max.get(t, 0.0))
            ydr[(s, t)] = model.addVar(name=f"ydr_{s}_{t}", vtype="B", lb=0, ub=1)
            shed[(s, t)] = model.addVar(name=f"shed_{s}_{t}", vtype="C", lb=0, ub=float(shd[(s, t)]["max_critical_shed_kw"]))
            for g in G:
                Rg[(s, t, g)] = model.addVar(name=f"Rg_{s}_{t}_{g}", vtype="C", lb=0, ub=float(gen[g]["max_kw"]))
            for b in B:
                Rb[(s, t, b)] = model.addVar(name=f"Rb_{s}_{t}_{b}", vtype="C", lb=0, ub=float(bat[b]["max_discharge_kw"]))
            for e in E:
                Re[(s, t, e)] = model.addVar(name=f"Re_{s}_{t}_{e}", vtype="C", lb=0, ub=float(ev[e]["max_discharge_kw"]))

    # scenario cost variables + CVaR
    Cscen = {}
    for s in S:
        Cscen[s] = model.addVar(name=f"C_{s}", vtype="C", lb=0)
    VaR = model.addVar(name="VaR", vtype="C", lb=0)
    z = {}
    for s in S:
        z[s] = model.addVar(name=f"z_{s}", vtype="C", lb=0)

    # objective coefficients (tracked in dicts)
    obj_terms = []
    for s in S:
        p = prob[s]
        for t in hours:
            for g in G:
                c = p * (float(gen[g]["no_load_cost_per_hour"]) * 0 + float(gen[g]["marginal_cost_per_kwh"]))
                obj_terms.append((c, P[(s, t, g)]))
            obj_terms.append((p * tariff[t], imp[(s, t)]))
            for b in B:
                c = p * float(bat[b]["cycle_cost_per_kwh"])
                obj_terms.append((c, chb[(s, t, b)]))
                obj_terms.append((c, dcb[(s, t, b)]))
            for e in E:
                c = p * float(ev[e]["cycle_cost_per_kwh"])
                obj_terms.append((c, che[(s, t, e)]))
                obj_terms.append((c, dce[(s, t, e)]))
            if t in dr_cost:
                obj_terms.append((p * dr_cost[t], cut[(s, t)]))
            for r in ("pv", "wind"):
                obj_terms.append((p * curtail_cost, curr[(s, t, r)]))
            obj_terms.append((p * shed_cost, shed[(s, t)]))
        # scenario cost equality: C_s = sum of scenario hourly costs
        hourly = []
        for t in hours:
            for g in G:
                hourly.append(float(gen[g]["marginal_cost_per_kwh"]) * P[(s, t, g)])
            hourly.append(tariff[t] * imp[(s, t)])
            for b in B:
                c = float(bat[b]["cycle_cost_per_kwh"])
                hourly.append(c * chb[(s, t, b)])
                hourly.append(c * dcb[(s, t, b)])
            for e in E:
                c = float(ev[e]["cycle_cost_per_kwh"])
                hourly.append(c * che[(s, t, e)])
                hourly.append(c * dce[(s, t, e)])
            if t in dr_cost:
                hourly.append(dr_cost[t] * cut[(s, t)])
            for r in ("pv", "wind"):
                hourly.append(curtail_cost * curr[(s, t, r)])
            hourly.append(shed_cost * shed[(s, t)])
        model.addCons(Cscen[s] == quicksum(hourly), name=f"Ceq_{s}")
        model.addCons(z[s] >= Cscen[s] - VaR, name=f"z1_{s}")
    # startup/no-load cost (here-and-now, not scenario-weighted per hour; counted once)
    for g in G:
        for t in hours:
            obj_terms.append((float(gen[g]["startup_cost"]), v[(g, t)]))
            obj_terms.append((float(gen[g]["no_load_cost_per_hour"]), u[(g, t)]))

    obj_expr = quicksum([c * x for (c, x) in obj_terms]) + tail_w * quicksum([prob[s] * z[s] for s in S])
    model.setObjective(obj_expr, sense="minimize")

    # ------------------------------------------------------------- constraints
    for s in S:
        p = prob[s]
        for t in hours:
            d = shd[(s, t)]
            lamL = float(d["load_multiplier"])
            lamG = float(d["grid_import_multiplier"])
            islanded = int(d["islanded"])
            resreq = float(d["reserve_requirement_kw"])
            evav = float(d["ev_availability_multiplier"])

            # rebound load at hour t from earlier curtailments
            reb_terms = []
            for tp in dr_hours:
                if dr_reb_hour[tp] == t:
                    reb_terms.append(dr_frac[tp] * cut[(s, tp)])
            reb = quicksum(reb_terms) if reb_terms else 0.0

            load_eff = lamL * base_load[t] - cut[(s, t)] + reb - shed[(s, t)]
            supply = (quicksum(P[(s, t, g)] for g in G) + imp[(s, t)]
                      + quicksum(float(bat[b]["discharge_efficiency"]) * dcb[(s, t, b)] for b in B)
                      + quicksum(float(ev[e]["discharge_efficiency"]) * dce[(s, t, e)] for e in E)
                      + genr[(s, t, "pv")] + genr[(s, t, "wind")])
            model.addCons(supply == load_eff, name=f"bal_{s}_{t}")

            # grid
            cap = lamG * gridcap[t]
            model.addCons(imp[(s, t)] <= cap, name=f"gcap_{s}_{t}")
            if islanded:
                model.addCons(imp[(s, t)] == 0, name=f"gisl_{s}_{t}")

            # generators
            for g in G:
                model.addCons(P[(s, t, g)] <= float(gen[g]["max_kw"]) * u[(g, t)], name=f"pmax_{s}_{t}_{g}")
                model.addCons(P[(s, t, g)] >= float(gen[g]["min_kw"]) * u[(g, t)], name=f"pmin_{s}_{t}_{g}")
                if t > 0:
                    model.addCons(P[(s, t, g)] - P[(s, t - 1, g)] <= float(gen[g]["ramp_up_kw"]), name=f"rampu_{s}_{t}_{g}")
                    model.addCons(P[(s, t - 1, g)] - P[(s, t, g)] <= float(gen[g]["ramp_down_kw"]), name=f"rampd_{s}_{t}_{g}")
                # reserve headroom
                model.addCons(Rg[(s, t, g)] <= float(gen[g]["max_kw"]) * u[(g, t)] - P[(s, t, g)], name=f"rg_{s}_{t}_{g}")

            # batteries
            for b in B:
                eta_c = float(bat[b]["charge_efficiency"])
                eta_d = float(bat[b]["discharge_efficiency"])
                if t == 0:
                    model.addCons(socb[(s, t, b)] == float(bat[b]["initial_soc_kwh"])
                                   + eta_c * chb[(s, t, b)] - dcb[(s, t, b)], name=f"socb_{s}_{t}_{b}")
                else:
                    model.addCons(socb[(s, t, b)] == socb[(s, t - 1, b)]
                                   + eta_c * chb[(s, t, b)] - dcb[(s, t, b)], name=f"socb_{s}_{t}_{b}")
                model.addCons(chb[(s, t, b)] + dcb[(s, t, b)] <= (float(bat[b]["max_charge_kw"]) + float(bat[b]["max_discharge_kw"])) * wbat[(s, t, b)], name=f"nss_{s}_{t}_{b}")
                model.addCons(Rb[(s, t, b)] <= float(bat[b]["max_discharge_kw"]), name=f"rb1_{s}_{t}_{b}")
                model.addCons(Rb[(s, t, b)] <= socb[(s, t, b)] - float(bat[b]["min_soc_kwh"]), name=f"rb2_{s}_{t}_{b}")
            if t == H - 1:
                for b in B:
                    model.addCons(socb[(s, t, b)] >= float(bat[b]["initial_soc_kwh"]), name=f"socbend_{s}_{t}_{b}")

            # EVs
            for e in E:
                arr = int(ev[e]["arrival_hour"])
                dep = int(ev[e]["departure_hour"])
                eta_c = float(ev[e]["charge_efficiency"])
                eta_d = float(ev[e]["discharge_efficiency"])
                connected = arr <= t <= dep
                if not connected:
                    model.addCons(che[(s, t, e)] == 0, name=f"evoff_c_{s}_{t}_{e}")
                    model.addCons(dce[(s, t, e)] == 0, name=f"evoff_d_{s}_{t}_{e}")
                    if t > 0:
                        model.addCons(soce[(s, t, e)] == soce[(s, t - 1, e)], name=f"evsoc_{s}_{t}_{e}")
                    continue
                model.addCons(che[(s, t, e)] <= float(ev[e]["max_charge_kw"]) * evav, name=f"evc_{s}_{t}_{e}")
                model.addCons(dce[(s, t, e)] <= float(ev[e]["max_discharge_kw"]) * evav, name=f"evd_{s}_{t}_{e}")
                if t == 0:
                    model.addCons(soce[(s, t, e)] == float(ev[e]["initial_soc_kwh"])
                                   + eta_c * che[(s, t, e)] - dce[(s, t, e)], name=f"evsoc_{s}_{t}_{e}")
                else:
                    model.addCons(soce[(s, t, e)] == soce[(s, t - 1, e)]
                                   + eta_c * che[(s, t, e)] - dce[(s, t, e)], name=f"evsoc_{s}_{t}_{e}")
                model.addCons(Re[(s, t, e)] <= float(ev[e]["max_discharge_kw"]) * evav, name=f"re1_{s}_{t}_{e}")
                model.addCons(Re[(s, t, e)] <= soce[(s, t, e)] - float(ev[e]["min_soc_kwh"]), name=f"re2_{s}_{t}_{e}")
                if t == dep:
                    model.addCons(soce[(s, t, e)] >= float(ev[e]["target_soc_kwh"]), name=f"evtgt_{s}_{t}_{e}")
            # for EVs not connected at t==0 we still need soc defined at t=0: handled above via t==0 branch only if connected; if not connected at t=0, add soc equality to initial
            for e in E:
                arr = int(ev[e]["arrival_hour"])
                if 0 < arr:
                    model.addCons(soce[(s, 0, e)] == float(ev[e]["initial_soc_kwh"]), name=f"evsoc0_{s}_{e}")

            # renewables
            model.addCons(genr[(s, t, "pv")] + curr[(s, t, "pv")] == float(d["pv_multiplier"]) * pv[t], name=f"renpv_{s}_{t}")
            model.addCons(genr[(s, t, "wind")] + curr[(s, t, "wind")] == float(d["wind_multiplier"]) * wind[t], name=f"renw_{s}_{t}")

            # DR
            if t in dr_max:
                model.addCons(cut[(s, t)] <= dr_max[t] * ydr[(s, t)], name=f"drb_{s}_{t}")
                for k in range(max_consec_dr + 1):
                    tt = t + k
                    if tt >= H:
                        break
                    terms = [ydr[(s, tt2)] for tt2 in range(t, min(tt, H - 1) + 1)]
                    model.addCons(quicksum(terms) <= max_consec_dr, name=f"drc_{s}_{t}_{k}")
            else:
                model.addCons(cut[(s, t)] == 0, name=f"drc0_{s}_{t}")

            # reserve requirement
            model.addCons(quicksum(Rg[(s, t, g)] for g in G)
                          + quicksum(Rb[(s, t, b)] for b in B)
                          + quicksum(Re[(s, t, e)] for e in E) >= resreq, name=f"res_{s}_{t}")

            # islanding stability
            if islanded:
                model.addCons(quicksum(Rg[(s, t, g)] for g in G) >= island_sync, name=f"isl_sync_{s}_{t}")
                gf_bats = [b for b in B if int(bat[b]["grid_forming"]) == 1]
                gf_cap = sum(float(bat[b]["max_discharge_kw"]) for b in gf_bats)
                model.addCons(quicksum(Rb[(s, t, b)] for b in gf_bats) >= gf_frac * gf_cap, name=f"isl_gf_{s}_{t}")
                inertia = quicksum(float(gen[g]["inertia_score"]) * u[(g, t)] for g in G)
                for b in gf_bats:
                    inertia = inertia + float(bat[b]["inertia_score_per_100kwh"]) * socb[(s, t, b)] / 100.0
                model.addCons(inertia >= island_inertia, name=f"isl_inert_{s}_{t}")

        # daily DR energy
        model.addCons(quicksum(cut[(s, t)] for t in dr_hours) <= max_daily_dr, name=f"drday_{s}")
        # emissions
        em = quicksum(float(gen[g]["emission_kg_per_kwh"]) * P[(s, t, g)] for g in G for t in hours)
        model.addCons(em <= em_cap, name=f"em_{s}")

    # ---------------------------------------------------------------- solve
    status = "unknown"
    objval = None
    try:
        model.optimize()
        status = model.getStatus()
        try:
            objval = model.getObjVal()
        except Exception:
            objval = None
        print("SCIP status:", status)
        print("Objective:", objval)
        print("NSols:", model.getNSols())
    except Exception as ex:
        print("Solver error:", ex)
        status = "error"

    # ------------------------------------------------------------- extract
    sol = model.getBestSol() if model.getNSols() > 0 else None

    def gv(var):
        if sol is None:
            return 0.0
        val = model.getVal(var)
        return max(0.0, val)

    rows = []
    for s in S:
        for t in hours:
            d = shd[(s, t)]
            # generators
            for g in G:
                rows.append({
                    "row_type": "generator", "scenario_id": s, "hour": t, "asset_id": g,
                    "commit": int(round(gv(u[(g, t)]))),
                    "power_kw": f"{gv(P[(s, t, g)]):.8f}", "charge_kw": "", "discharge_kw": "",
                    "soc_kwh": "", "curtail_kw": "", "shed_kw": "",
                    "reserve_kw": f"{gv(Rg[(s, t, g)]):.8f}",
                })
            # storage
            for b in B:
                rows.append({
                    "row_type": "storage", "scenario_id": s, "hour": t, "asset_id": b,
                    "commit": "", "power_kw": "",
                    "charge_kw": f"{gv(chb[(s, t, b)]):.8f}",
                    "discharge_kw": f"{gv(dcb[(s, t, b)]):.8f}",
                    "soc_kwh": f"{gv(socb[(s, t, b)]):.8f}",
                    "curtail_kw": "", "shed_kw": "",
                    "reserve_kw": f"{gv(Rb[(s, t, b)]):.8f}",
                })
            # ev clusters
            for e in E:
                rows.append({
                    "row_type": "ev_cluster", "scenario_id": s, "hour": t, "asset_id": e,
                    "commit": "", "power_kw": "",
                    "charge_kw": f"{gv(che[(s, t, e)]):.8f}",
                    "discharge_kw": f"{gv(dce[(s, t, e)]):.8f}",
                    "soc_kwh": f"{gv(soce[(s, t, e)]):.8f}",
                    "curtail_kw": "", "shed_kw": "",
                    "reserve_kw": f"{gv(Re[(s, t, e)]):.8f}",
                })
            # grid
            rows.append({
                "row_type": "grid", "scenario_id": s, "hour": t, "asset_id": "grid",
                "commit": "", "power_kw": f"{gv(imp[(s, t)]):.8f}",
                "charge_kw": "", "discharge_kw": "", "soc_kwh": "",
                "curtail_kw": "", "shed_kw": "", "reserve_kw": "",
            })
            # renewables
            for r in ("pv", "wind"):
                rows.append({
                    "row_type": "renewable", "scenario_id": s, "hour": t, "asset_id": r,
                    "commit": "", "power_kw": f"{gv(genr[(s, t, r)]):.8f}",
                    "charge_kw": "", "discharge_kw": "", "soc_kwh": "",
                    "curtail_kw": f"{gv(curr[(s, t, r)]):.8f}", "shed_kw": "", "reserve_kw": "",
                })
            # demand response
            rows.append({
                "row_type": "demand_response", "scenario_id": s, "hour": t, "asset_id": "flex_load",
                "commit": "", "power_kw": "", "charge_kw": "", "discharge_kw": "", "soc_kwh": "",
                "curtail_kw": f"{gv(cut[(s, t)]):.8f}", "shed_kw": "", "reserve_kw": "",
            })
            # load shed
            rows.append({
                "row_type": "load_shed", "scenario_id": s, "hour": t, "asset_id": "critical_load",
                "commit": "", "power_kw": "", "charge_kw": "", "discharge_kw": "", "soc_kwh": "",
                "curtail_kw": "", "shed_kw": f"{gv(shed[(s, t)]):.8f}", "reserve_kw": "",
            })

    # ------------------------------------------------------------- validate
    checks = []
    checks.append(("row_count", len(rows) == len(S) * H * 12, len(rows)))
    # commit consistency
    ok = True
    for g in G:
        for t in hours:
            vals = set()
            for s in S:
                vals.add(int(round(gv(u[(g, t)]))))
            if len(vals) > 1:
                ok = False
    checks.append(("commit_consistency", ok, ""))
    # power balance residual
    maxres = 0.0
    for s in S:
        for t in hours:
            d = shd[(s, t)]
            reb = sum(dr_frac[tp] * gv(cut[(s, tp)]) for tp in dr_hours if dr_reb_hour[tp] == t)
            supply = (sum(gv(P[(s, t, g)]) for g in G) + gv(imp[(s, t)])
                      + sum(float(bat[b]["discharge_efficiency"]) * gv(dcb[(s, t, b)]) for b in B)
                      + sum(float(ev[e]["discharge_efficiency"]) * gv(dce[(s, t, e)]) for e in E)
                      + gv(genr[(s, t, "pv")]) + gv(genr[(s, t, "wind")]))
            demand = float(d["load_multiplier"]) * base_load[t] - gv(cut[(s, t)]) + reb - gv(shed[(s, t)])
            maxres = max(maxres, abs(supply - demand))
    checks.append(("power_balance", maxres < 1e-3, f"maxres={maxres:.6f}"))
    # grid cap / islanding
    ok = True
    for s in S:
        for t in hours:
            d = shd[(s, t)]
            cap = float(d["grid_import_multiplier"]) * gridcap[t]
            if gv(imp[(s, t)]) > cap + 1e-4:
                ok = False
            if int(d["islanded"]) == 1 and gv(imp[(s, t)]) > 1e-4:
                ok = False
    checks.append(("grid_limits", ok, ""))
    # reserve
    ok = True
    for s in S:
        for t in hours:
            d = shd[(s, t)]
            res = (sum(gv(Rg[(s, t, g)]) for g in G) + sum(gv(Rb[(s, t, b)]) for b in B)
                   + sum(gv(Re[(s, t, e)]) for e in E))
            if res < float(d["reserve_requirement_kw"]) - 1e-3:
                ok = False
    checks.append(("reserve", ok, ""))
    # emissions
    ok = True
    for s in S:
        em = sum(float(gen[g]["emission_kg_per_kwh"]) * gv(P[(s, t, g)]) for g in G for t in hours)
        if em > em_cap + 1e-3:
            ok = False
    checks.append(("emissions", ok, ""))
    # DR daily
    ok = True
    for s in S:
        tot = sum(gv(cut[(s, t)]) for t in dr_hours)
        if tot > max_daily_dr + 1e-3:
            ok = False
    checks.append(("dr_daily", ok, ""))
    # battery end soc
    ok = True
    for s in S:
        for b in B:
            if gv(socb[(s, H - 1, b)]) < float(bat[b]["initial_soc_kwh"]) - 1e-3:
                ok = False
    checks.append(("battery_end_soc", ok, ""))
    # EV target
    ok = True
    for s in S:
        for e in E:
            dep = int(ev[e]["departure_hour"])
            if gv(soce[(s, dep, e)]) < float(ev[e]["target_soc_kwh"]) - 1e-3:
                ok = False
    checks.append(("ev_target", ok, ""))
    # shedding cap
    ok = True
    for s in S:
        for t in hours:
            cap = float(shd[(s, t)]["max_critical_shed_kw"])
            if gv(shed[(s, t)]) > cap + 1e-4:
                ok = False
    checks.append(("shed_cap", ok, ""))

    print("Validation:")
    for name, okv, extra in checks:
        print(f"  {name}: {'PASS' if okv else 'FAIL'} {extra}")

    # ------------------------------------------------------------- write
    os.makedirs(OUT_DIR, exist_ok=True)
    header = ["row_type", "scenario_id", "hour", "asset_id", "commit", "power_kw",
              "charge_kw", "discharge_kw", "soc_kwh", "curtail_kw", "shed_kw", "reserve_kw"]
    with open(SOL_PATH, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=header)
        w.writeheader()
        for r in rows:
            w.writerow(r)
    print("Wrote", SOL_PATH, "rows:", len(rows))
    print("Final status:", status, "obj:", objval)
    try:
        model.free()
    except Exception:
        pass

if __name__ == "__main__":
    main()
